    """V3: _good_control must refuse when bindings not provided or mismatched."""
    bindings = {'model_sha256': _h(0), 'workload_sha256': _h(1),
                'build_sha256': _h(2), 'executable_sha256': _h(3)}
    ctrl = [{'kind': 'COMPARATOR_ONLY', 'scope': 'COMPARE_ONLY',
             'exit_code': 1, 'detected': True, 'artifact_sha256': _h(10),
             **bindings}]
    # Without bindings -> MISSING_BINDING
    st, reason = qv._good_control(ctrl, None)
    assert st == 'NOT_CHECKED' and reason == 'MISSING_BINDING', f'Expected MISSING_BINDING, got {st},{reason}'
    # With correct bindings -> QUALIFIED
    st, reason = qv._good_control(ctrl, bindings)
    assert st == 'QUALIFIED', f'Expected QUALIFIED, got {st},{reason}'
    # With wrong bindings -> BINDING_MISMATCH
    wrong = dict(bindings, model_sha256=_h(99))
    st, reason = qv._good_control(ctrl, wrong)
    assert st == 'REFUSED' and reason == 'BINDING_MISMATCH', f'Expected BINDING_MISMATCH, got {st},{reason}'
